-- =============================================================================
-- PASSWORD BREACH MONITORING (PBM) DATABASE — MYSQL & MARIADB DUMP SCRIPT
-- Target Database: `Case-Study`
-- Compatibility: MySQL 5.7+, MySQL 8.0+, MariaDB 10.3+
-- Encoding: utf8mb4 / utf8mb4_unicode_ci
-- =============================================================================

-- Step 1: Create and select the database `Case-Study`
CREATE DATABASE IF NOT EXISTS `Case-Study` 
  DEFAULT CHARACTER SET utf8mb4 
  COLLATE utf8mb4_unicode_ci;

USE `Case-Study`;

-- Step 2: Drop existing tables if re-initializing
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `sources`;
DROP TABLE IF EXISTS `case_studies`;
DROP TABLE IF EXISTS `breaches`;
SET FOREIGN_KEY_CHECKS = 1;

-- -----------------------------------------------------------------------------
-- Table structure for `breaches`
-- -----------------------------------------------------------------------------
CREATE TABLE `breaches` (
  `id` VARCHAR(64) NOT NULL,
  `breach_name` VARCHAR(255) NOT NULL,
  `organization` VARCHAR(255) NOT NULL,
  `industry` VARCHAR(100) NOT NULL,
  `breach_date` VARCHAR(30) NOT NULL,
  `discovery_date` VARCHAR(30) NOT NULL,
  `affected_records` BIGINT NOT NULL,
  `severity` VARCHAR(50) NOT NULL,
  `breach_type` VARCHAR(100) NOT NULL,
  `attack_vector` VARCHAR(100) NOT NULL,
  `data_exposed` TEXT NOT NULL,
  `root_cause` TEXT NOT NULL,
  `status` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `idx_breach_date` (`breach_date`),
  INDEX `idx_severity` (`severity`),
  INDEX `idx_industry` (`industry`),
  INDEX `idx_attack_vector` (`attack_vector`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Table structure for `case_studies`
-- -----------------------------------------------------------------------------
CREATE TABLE `case_studies` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `breach_id` VARCHAR(64) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `subtitle` VARCHAR(255) NOT NULL,
  `date` VARCHAR(30) NOT NULL,
  `severity` VARCHAR(50) NOT NULL,
  `executive_summary` TEXT NOT NULL,
  `timeline_json` MEDIUMTEXT NOT NULL,
  `response` TEXT NOT NULL,
  `attack_vector_tags` TEXT NOT NULL,
  `root_cause` TEXT NOT NULL,
  `data_exposed_tags` TEXT NOT NULL,
  `impact_metrics` TEXT NOT NULL,
  `lessons_learned` TEXT NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `idx_cs_breach_id` (`breach_id`),
  CONSTRAINT `fk_case_studies_breach` FOREIGN KEY (`breach_id`) REFERENCES `breaches` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- Table structure for `sources`
-- -----------------------------------------------------------------------------
CREATE TABLE `sources` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `breach_id` VARCHAR(64) NOT NULL,
  `source_type` VARCHAR(100) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `authority_or_publisher` VARCHAR(255) NOT NULL,
  `url` TEXT NOT NULL,
  `publication_year` VARCHAR(30) NOT NULL,
  `citation_note` TEXT,
  PRIMARY KEY (`id`),
  INDEX `idx_sources_breach_id` (`breach_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

